import { advanceTal1 } from "../src/tal/rules";
import { advanceOsk1, advanceOskFen } from "../src/osk/rules";
import { advanceFen1, advanceFen2 } from "../src/fen/rules";

test("advanceVok1: nim -> pex succeeds from initial state", () => {
