  let w = createInitialWorld();
  w = advanceTal1(w);   // tal: pex (advanceZef1の前提)
  w = advanceZef1(w);   // zef: pex
  w = advanceOsk1(w);   // osk: pex (advanceVok2の前提 I4)
  w = advanceVok1(w);   // vok: pex
  const w2 = advanceVok2(w);
  expect(w2.vok).toBe("dor");
});

