  w = advanceZef1(w);   // zef: pex (tal=pexなので成功)
  w = advanceOsk1(w);   // osk: pex (advanceFen1の前提)
  w = advanceFen1(w);   // fen: pex (osk=pexなので成功、advanceZef2の前提)
  const w2 = advanceZef2(w);
  expect(w2.zef).toBe("dor");
});

