  const w2 = advanceOsk1(w);
  expect(w2.osk).toBe("pex");
});

test("advanceOsk1: fails if Osk is not 'nim'", () => {
  let w = createInitialWorld();
  w = advanceOsk1(w); // osk: pex
  expect(() => advanceOsk1(w)).toThrow();
